from abc import ABC


class BaseRepository(ABC):
    def __init__(self, db):
        self.db = db

    def _row_to_dict(self, row):
        if row is None:
            return None
        return dict(row)

    def _rows_to_dicts(self, rows):
        return [dict(row) for row in rows]

from .base_repository import BaseRepository


class UserRepository(BaseRepository):
    def create(self, username, password_hash, email):
        cursor = self.db.execute(
            "INSERT INTO user (username, password_hash, email) VALUES (?, ?, ?)",
            (username, password_hash, email),
        )
        self.db.commit()
        return {"id": cursor.lastrowid, "username": username}

    def find_by_username(self, username):
        row = self.db.execute(
            "SELECT * FROM user WHERE username = ?", (username,)
        ).fetchone()
        return self._row_to_dict(row)

    def exists_by_username(self, username):
        row = self.db.execute(
            "SELECT id FROM user WHERE username = ?", (username,)
        ).fetchone()
        return row is not None

    def exists_by_id(self, user_id):
        row = self.db.execute(
            "SELECT id FROM user WHERE id = ?", (user_id,)
        ).fetchone()
        return row is not None

    def get_email(self, user_id):
        row = self.db.execute(
            "SELECT email FROM user WHERE id = ?", (user_id,)
        ).fetchone()
        if row is None:
            return None
        return row["email"]

from .base_repository import BaseRepository


class TaskRepository(BaseRepository):
    def create(self, owner_id, title, status, created_at):
        cursor = self.db.execute(
            "INSERT INTO task (title, status, created_at, owner_id) VALUES (?, ?, ?, ?)",
            (title, status, created_at, owner_id),
        )
        self.db.commit()
        task_id = cursor.lastrowid
        row = self.db.execute(
            "SELECT * FROM task WHERE id = ? AND owner_id = ?",
            (task_id, owner_id),
        ).fetchone()
        return self._row_to_dict(row)

    def find_by_id(self, task_id, owner_id):
        row = self.db.execute(
            "SELECT * FROM task WHERE id = ? AND owner_id = ?",
            (task_id, owner_id),
        ).fetchone()
        return self._row_to_dict(row)

    def find_all_by_owner(self, owner_id):
        rows = self.db.execute(
            "SELECT * FROM task WHERE owner_id = ? ORDER BY created_at DESC",
            (owner_id,),
        ).fetchall()
        return self._rows_to_dicts(rows)

    def update(self, task_id, owner_id, title, status):
        self.db.execute(
            "UPDATE task SET title = ?, status = ? WHERE id = ? AND owner_id = ?",
            (title, status, task_id, owner_id),
        )
        self.db.commit()

